from pathlib import Path
import json,inspect
import numpy as np,pandas as pd,networkx as nx
from scipy.stats import pearsonr
from star_presence_entropy import bits,active_n
from hub_entropy_regressions import Fit,holm
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.backends.backend_pdf import PdfPages

def normalized_entropy(M,den):return float(bits(M))/den if M.sum()>0 else np.nan
def report(root,out,skip_network_plots=False):
 root=Path(root);out=Path(out);coverage=pd.read_csv(out/'coverage_and_hubs.csv');names=pd.read_csv(root/'2025-26/team_season_topics/player_games.csv').drop_duplicates('PLAYER_ID').set_index('PLAYER_ID').PLAYER_NAME.to_dict();rng=np.random.default_rng(20261119);rows=[]
 for z in coverage.itertuples():
  folder=out/z.team;frames={name:pd.read_csv(folder/(name+'_evaluation.csv'),index_col=0) for name in ['original','predicted','actual','later_present']};P,M,A,LP=[frames[name].to_numpy(float) for name in ['original','predicted','actual','later_present']];den=np.log2(active_n(P+A)-1);hp,hm,ha,hl=[normalized_entropy(B,den) for B in [P,M,A,LP]];row=z._asdict();row.pop('Index',None);row.update(entropy_original=hp,entropy_predicted=hm,entropy_actual=ha,entropy_later_present=hl,predicted_change=hm-hp,actual_change=ha-hp,concurrent_period_change=ha-hl,prediction_error=ha-hm,normalization_log2=den,original_passes=P.sum(),actual_passes=A.sum(),primary_eligible=z.first20_hub_present_games>=15 and z.later_hub_absent_games>=10 and A.sum()>0,concurrent_eligible=z.first20_hub_present_games>=15 and z.later_hub_absent_games>=10 and z.later_hub_present_games>=15 and A.sum()>0 and LP.sum()>0,actual_equal_count_change=np.nan,concurrent_equal_count_change=np.nan,equal_count_passes=np.nan,edge_distance_predicted_actual=np.nan,edge_distance_deletion_actual=np.nan)
  if A.sum()>0:
   def equal_change(B):
    N=int(min(B.sum(),A.sum()));pair=[]
    for C in [B,A]:
     count=C.astype(int);assert np.array_equal(C,count);S=rng.multivariate_hypergeometric(count.ravel(),N,size=500).reshape(500,*C.shape);pair.append(bits(S)/den)
    return float((pair[1]-pair[0]).mean()),N
   row['actual_equal_count_change'],row['equal_count_passes']=equal_change(P)
   if LP.sum()>0:row['concurrent_equal_count_change'],_=equal_change(LP)
   D=P.copy();hi=frames['original'].index.astype(int).tolist().index(z.hub_id);D[hi]=0;D[:,hi]=0;row['edge_distance_predicted_actual']=float(abs(M/M.sum()-A/A.sum()).sum()/2);row['edge_distance_deletion_actual']=float(abs(D/D.sum()-A/A.sum()).sum()/2)
  rows.append(row)
 d=pd.DataFrame(rows).sort_values(['ec_index','team'],ascending=[False,True]);d.insert(0,'ec_rank',range(1,len(d)+1));
 for name in ['original','predicted','actual','later_present']:d['entropy_'+name+'_bits']=d['entropy_'+name]*d.normalization_log2
 d.to_csv(out/'team_entropy_and_ec.csv',index=False);statistics=[];models={}
 for name,column,eligibility in [('primary_equal_count','actual_equal_count_change','primary_eligible'),('raw_training_reference','actual_change','primary_eligible'),('late_present_equal_count','concurrent_equal_count_change','concurrent_eligible'),('late_present_raw','concurrent_period_change','concurrent_eligible')]:
  q=d[d[eligibility]].copy();x=q.ec_index.to_numpy();y=q[column].to_numpy()
  if len(q)<4:continue
  fit=Fit(x,y);r,p=pearsonr(x,y);ci=fit.conf_int()[1];statistics.append(dict(analysis=name,n=len(q),r=r,r_squared=fit.rsquared,slope=fit.params[1],slope_per_001=fit.params[1]*.01,hc3_p=fit.pvalues[1],pearson_p=p,ci_low=ci[0],ci_high=ci[1]));models[name]=(q,x,y,fit)
 s=pd.DataFrame(statistics)
 if len(s):s['holm_all_4']=holm(s.hc3_p);s.to_csv(out/'ec_entropy_regressions.csv',index=False)
 with PdfPages(out/'entropy_changes_and_regressions.pdf') as pdf:
  fig,ax=plt.subplots(figsize=(15,7));x=np.arange(len(d));ax.bar(x-.18,d.predicted_change,.36,label='Predicted minus original');ax.bar(x+.18,d.actual_change,.36,label='Actual absent minus original');ax.axhline(0,c='grey');ax.set_xticks(x,d.team,rotation=45);ax.set_ylabel('Fixed-reference normalized outgoing entropy change');ax.set_title('2025–26 | teams ordered by first-20 passing-only EC concentration\nHub identity: most passes sent + received during first 20 games');ax.legend();fig.text(.5,.015,'No later absence comparison is plotted as zero. Original = first-20 hub-present games; actual = later missed games.\nPredicted redistribution is frozen after game 20. Differences can also reflect temporal drift and other availability changes.',ha='center',fontsize=10);fig.tight_layout(rect=[0,.09,1,.94]);fig.savefig(out/'league_entropy_changes.png',dpi=150);pdf.savefig(fig);plt.close(fig)
  for start in range(0,30,6):
   fig,axes=plt.subplots(2,3,figsize=(17,10));subset=d.iloc[start:start+6]
   for ax,z in zip(axes.flat,subset.itertuples()):
    values=[z.entropy_original,z.entropy_predicted,z.entropy_actual];ax.plot(range(3),values,marker='o');ax.set_xticks(range(3),['Hub present\ntraining','Role-weighted\nprediction','Actual later\nabsence']);ax.set_xlim(-.25,2.25);ax.grid(alpha=.2);ax.set_title(f'#{z.ec_rank} {z.team}: {z.hub_name}\nEC index {z.ec_index:.4f} | train present {z.first20_hub_present_games}, later absent {z.later_hub_absent_games}',fontsize=10)
    for j,v in enumerate(values):
     if np.isfinite(v):ax.annotate(f'{v:.4f}',(j,v),xytext=(0,7),textcoords='offset points',ha='center',fontsize=9)
    if not np.isfinite(values[2]):ax.text(2,np.nanmean(values),'No observed later absence',rotation=90,ha='center',fontsize=8)
   fig.suptitle('Outgoing conditional entropy | same denominator within team',fontsize=16);fig.tight_layout(rect=[0,.04,1,.94]);fig.savefig(out/f'entropy_teams_{start+1:02d}_{start+len(subset):02d}.png',dpi=140);pdf.savefig(fig);plt.close(fig)
  if models:
   fig,axes=plt.subplots(2,2,figsize=(15,11))
   for ax,(name,(q,x,y,fit)) in zip(axes.flat,models.items()):
    ax.scatter(x,y,c='#287b9b')
    for team,xx,yy in zip(q.team,x,y):ax.annotate(team,(xx,yy),xytext=(3,3),textcoords='offset points',fontsize=8)
    grid=np.linspace(x.min(),x.max(),100);pred=fit.prediction(grid);ax.plot(grid,pred['mean'],c='firebrick');ax.fill_between(grid,pred.mean_ci_lower,pred.mean_ci_upper,color='firebrick',alpha=.1);z=s[s.analysis.eq(name)].iloc[0];ax.axhline(0,c='grey',lw=.6);ax.set_xlabel('First-20 passing-only EC concentration index');ax.set_ylabel('Observed hub-absent minus hub-present entropy');ax.set_title(f'{name}\nn={len(q)}; r={z.r:+.3f}; R²={z.r_squared:.3f}; HC3 p={z.hc3_p:.3f}',fontsize=10)
   for ax in axes.flat[len(models):]:ax.axis('off')
   fig.suptitle('Actual entropy change regressed on EC concentration\nEqual-pass count primary; raw counts and later-present reference are sensitivity checks',fontsize=15);fig.tight_layout(rect=[0,.03,1,.92]);fig.savefig(out/'ec_entropy_regressions.png',dpi=150);pdf.savefig(fig);plt.close(fig)
 if not skip_network_plots:
  with PdfPages(out/'all_30_hub_networks.pdf') as pdf:
   for z in d.itertuples():
    folder=out/z.team;frames=[pd.read_csv(folder/(name+'_evaluation.csv'),index_col=0) for name in ['original','predicted','actual']];ids=frames[0].index.astype(int).tolist();P,M,A=[f.to_numpy(float) for f in frames];matrices=[P,M,A];U=sum(B/B.sum() for B in matrices if B.sum()>0);G=nx.from_numpy_array(U+U.T);G=G.subgraph(np.flatnonzero(U.sum(0)+U.sum(1)>0)).copy();opts=dict(seed=42,weight=None,iterations=400,k=1.5/np.sqrt(len(G)))
    if 'method' in inspect.signature(nx.spring_layout).parameters:opts['method']='force'
    pos=nx.spring_layout(G,**opts);coords=np.array(list(pos.values()));lo=coords.min(0)-.25;hi=coords.max(0)+.25;scale=max((1000*B/B.sum()).max() for B in matrices if B.sum()>0);fig,axes=plt.subplots(1,3,figsize=(24,9))
    for ax,B,title,h in zip(axes,matrices,[f'Original: first-20 hub-present games ({z.first20_hub_present_games})','Predicted: hub removed, role-weighted redistribution',f'Actual later hub-absent games ({z.later_hub_absent_games})'],[z.entropy_original,z.entropy_predicted,z.entropy_actual]):
     if B.sum()==0:ax.text(.5,.5,'No observed later absence\nActual comparison unavailable',ha='center',va='center',transform=ax.transAxes,fontsize=15);ax.set_title(title);ax.axis('off');continue
     active=np.flatnonzero(B.sum(0)+B.sum(1)>0);H=nx.DiGraph();H.add_nodes_from(active);edges=[(i,j) for i in active for j in active if B[i,j]>0];H.add_edges_from(edges);size=[16000*(B.sum(0)[i]+B.sum(1)[i])/(2*B.sum()) for i in H];nx.draw_networkx_edges(H,pos,edgelist=edges,width=[.1+5*1000*B[i,j]/B.sum()/scale for i,j in edges],alpha=.27,edge_color='#3a7b99',arrows=True,arrowsize=8,node_size=size,connectionstyle='arc3,rad=.07',ax=ax);nx.draw_networkx_nodes(H,pos,node_size=size,node_color=['#e59d47' if ids[i]==z.hub_id else '#dcebef' for i in H],edgecolors='#536b76',ax=ax);nx.draw_networkx_labels(H,pos,labels={i:str(names.get(ids[i],ids[i])).replace(' ','\n',1) for i in H},font_size=6.5,ax=ax);ax.set_xlim(lo[0],hi[0]);ax.set_ylim(lo[1],hi[1]);ax.axis('off');ax.set_title(title+f'\nOutgoing entropy {h:.4f}',fontsize=12)
    spec=json.loads((folder/'frozen_specification.json').read_text());top=sorted(zip(spec['selection']['training_player_ids'],spec['replacement_weights']),key=lambda p:-p[1])[:3];replacements=', '.join(f'{names.get(pid,pid)} {w:.0%}' for pid,w in top);fig.suptitle(f'#{z.ec_rank} {z.team} | passing hub: {z.hub_name} | first-20 EC index {z.ec_index:.4f}\nReplacement shares of hub minutes: {replacements}',fontsize=16);fig.text(.5,.02,'Node areas use each graph’s own passing-involvement shares; widths per 1,000 passes share a scale; Fruchterman–Reingold positions fixed.\nHub identity and EC use first 20 games only. Prediction uses first-20 minutes, historical replacement gains and previous-season NBA position labels.\nHub incident edges are reassigned by predicted extra-minute shares; self-pass routes are excluded. Later minutes/passes never construct the prediction.',ha='center',fontsize=10);fig.tight_layout(rect=[0,.1,1,.91]);fig.savefig(folder/(z.team+'_three_networks.png'),dpi=140);pdf.savefig(fig);plt.close(fig);print('Plotted',z.team,flush=True)
 q=d[d.primary_eligible];observed=d[d.actual_passes.gt(0)];summary=dict(teams=30,observed_later_absence_pairs=len(observed),primary_regression_teams=len(q),later_present_sensitivity_teams=int(d.concurrent_eligible.sum()),median_predicted_edge_distance=float(q.edge_distance_predicted_actual.median()),median_deleted_edge_distance=float(q.edge_distance_deletion_actual.median()),redistribution_improves_teams=int((q.edge_distance_predicted_actual<q.edge_distance_deletion_actual-1e-8).sum()),primary_mean_actual_entropy_change=float(q.actual_equal_count_change.mean()));(out/'summary.json').write_text(json.dumps(summary,indent=2));print(s.to_string(index=False),flush=True);print(json.dumps(summary,indent=2),flush=True)
 text=['# First-20 passing hubs and role-weighted redistribution | 2025–26','## Definitions','The passing hub is the player with the largest sum of outgoing and incoming directed pass counts in the first twenty regular-season games (ties: lowest player ID). The EC index is a separate team measure: L1 eigenvector shares on A+Aᵀ, concentration (sum(p_i²)−1/N)/(1−1/N), using only active passing nodes in that first-20 network. No shooting edges or later-game data enter identity/index.','Original panel: observed first-20 games in which the selected hub appeared. Middle: counterfactual passing-share prediction frozen after game20. Third: all later missed games within the valid team window. Later hub-present games are also exported as a concurrent-reference sensitivity; they never train the prediction.','## Replacement minutes and depth','Official NBA CommonTeamRoster positions from the COMPLETED PREVIOUS season are used, so current/future roster moves are not exposed to the model. Candidates are only players observed in training. These are broad G/F/C position labels, not official historical depth-chart ordering. Depth rank is inferred from first-20 hub-present minutes within the overlapping position group. Missing/rookie position labels receive a neutral fallback.','Convert training hub-present minutes to a 240-minute regulation rotation. Remove the hub. Candidate fallback weight = available minute capacity (48−baseline minutes) × position match / inferred position depth rank. Position match is 1 for overlapping known positions, 0.5 if either is unknown and 0.25 otherwise. Among matching candidates, depth ranks follow baseline minutes excluding the hub.','If earlier hub-absent games occur WITHIN the first 20, calculate positive teammate minute gains relative to hub-present games, normalize, and blend with fallback weights using n_early_abs/(n_early_abs+5). This is a declared shrinkage convention, not tuned on later results. Allocate the removed hub minutes by those weights, capping each player at48 and redistributing excess among uncapped players. Actual later minutes, later roster arrivals and later passing are never inputs.','## Passing redistribution','Keep all nonhub-to-nonhub edges unchanged. For each outgoing hub edge to j, distribute its weight across replacements, excluding j to avoid a self-pass. For each incoming edge from i to the hub, distribute it across replacement receivers excluding i. Renormalize replacement weights for each excluded endpoint. The hub row/column and diagonal are zero; total team pass mass is preserved. This assumes replacements inherit the hub’s connections; it is a model to test, not observed behavior. Minute weights are NOT also multiplied into the nonhub edges, which would double-count replacement activity.','The forecast is a relative passing-pattern counterfactual, not a forecast of game pace or total pass volume. Node areas and edge widths normalize within context. Player layouts can use the displayed union for readability, but layout does not enter any prediction or metric.','## Entropy and regression','Outgoing conditional entropy H(receiver|passer), weighted by passes, is exported in a fixed within-team normalized form using log2(N_union_active−1), where union uses training-present and observed-later-absence players for evaluation. All three panels share the denominator. Original raw matrices remain available.','Primary Y = actual later-absence entropy − first-20 hub-present entropy, after 500 equal-total-pass-count subsamples of the two observed integer-count matrices. X = first-20 passing-only EC concentration. At least15 training hub-present and10 later hub-absent games are required for the fit. Low-exposure teams remain illustrated but never enter that line. Raw-count results are a sensitivity.','An early/late comparison can mix absence effects with time drift. Therefore a separate sensitivity compares later hub-absent versus later hub-present games, requiring ≥15 later hub-present games as well. That reference uses later data only as an outcome comparator, never to select the hub or construct the prediction. No opponent/lineup controls are imposed; neither difference is a causal effect.','OLS/HC3 t uncertainty, conventional Pearson p and Holm across the four declared analyses are exported. This follows extensive earlier exploration and remains exploratory. Subsampling ranges are not confidence intervals for causal behavior.','## Coverage and validation',json.dumps(summary,indent=2),'A trade-safe evaluation window stops14 days before the first recorded other-team appearance when applicable; this retrospective cohort guard is not used to forecast a trade. Empty tracking profiles require independent zero confirmation. All frozen prediction hashes are retained. No observed absence is represented as unavailable, not entropy zero.','## Limitations','First20 is a small training sample; role order is a proxy, not an official NBA depth chart. Candidate availability and teammate roles can change after game20. The prediction stays fixed through the later season, making long absences and roster changes difficult. Missing position information is explicit. Temporal drift, co-absence, opponent strength and finite counts remain. Higher entropy means greater recipient variety, not better offense.']
 (out/'METHOD_AND_RESULTS.md').write_text('\n\n'.join(text))
